/// Errors that happen after `createAnimation` returned, such as a lost
/// surface or a decode failure mid-playback.
/// Returns a broadcast [Stream] of events from the `streamErrors` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<AnimationErrorMessage> streamErrors({String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel streamErrorsChannel = EventChannel(
    'dev.flutter.pigeon.webm_texture.WebmTextureEvents.streamErrors$instanceName',
    pigeonMethodCodec,
  );
  return streamErrorsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as AnimationErrorMessage;
  });
}

